#!/usr/bin/env node
/**
 * gen-airfoil-catalog.mjs — Dump the BladeProfileLibraryEngine catalog
 * to `data/catalogs/airfoil-profiles.json` so downstream loaders can
 * iterate the library without booting the TypeScript runtime.
 *
 * The JSON is regenerated by hand (run this script) whenever the
 * catalog definition in BladeProfileLibraryEngine.buildCatalog changes.
 */

import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);

// Stand up a minimal TS shim via esbuild-runner would be heavy — instead
// we re-derive the catalog with the same rules here so the JSON matches
// the engine exactly. Keep the two in sync manually (covered by the
// test "every catalog entry generates without throwing").

const rows = [];

// 4-digit symmetric NACA 00XX.
for (const t of [6, 8, 9, 10, 12, 15, 18, 21, 24]) {
  const tt = String(t).padStart(2, "0");
  rows.push({
    designation: `NACA 00${tt}`,
    family: "naca-4",
    maxCamberPct: 0,
    maxCamberPosTenths: 0,
    thicknessPct: t,
  });
}

// 4-digit cambered NACA MPXX, M∈1..6, P∈2..5, XX∈{08,09,10,12,15,18,21}.
for (let M = 1; M <= 6; M++) {
  for (let P = 2; P <= 5; P++) {
    for (const t of [8, 9, 10, 12, 15, 18, 21]) {
      const digits = `${M}${P}${String(t).padStart(2, "0")}`;
      rows.push({
        designation: `NACA ${digits}`,
        family: "naca-4",
        maxCamberPct: M,
        maxCamberPosTenths: P,
        thicknessPct: t,
      });
    }
  }
}

// 5-digit series NACA LPSTT, mean lines 210/220/230/240/250 × TT∈{09,10,12,15,18,21}.
for (const meanLine of ["210", "220", "230", "240", "250"]) {
  for (const t of [9, 10, 12, 15, 18, 21]) {
    const digits = `${meanLine}${String(t).padStart(2, "0")}`;
    rows.push({
      designation: `NACA ${digits}`,
      family: "naca-5",
      maxCamberPct: parseInt(meanLine[0], 10),
      maxCamberPosTenths: parseInt(meanLine[1], 10),
      thicknessPct: t,
    });
  }
}

const out = {
  schemaVersion: 1,
  generator: "gen-airfoil-catalog.mjs",
  source: "NACA Report 460 (4-digit) + Abbott & von Doenhoff 'Theory of Wing Sections' Appendix III (5-digit)",
  count: rows.length,
  profiles: rows,
};

const dest = path.resolve("data/catalogs/airfoil-profiles.json");
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.writeFileSync(dest, JSON.stringify(out, null, 2) + "\n", "utf8");
console.log(`wrote ${rows.length} profile catalog entries → ${dest}`);
